void insertion(std::vector<int>&a){for(std::size_t i=1;i<a.size();++i){int x=a[i];auto j=i;while(j>0&&x<a[j-1]){a[j]=a[j-1];--j;}a[j]=x;}}
bool contract(const std::vector<int>&source,const std::vector<int>&result){return std::is_sorted(result.begin(),result.end())&&std::is_permutation(source.begin(),source.end(),result.begin(),result.end());}
int main(){int n;if(!(std::cin>>n)||n<0||n>128){std::cout<<"invalid\n";return 0;}
 std::vector<int>base;for(int i=0;i<n;++i){int x;if(!(std::cin>>x)||x< -10000||x>10000){std::cout<<"invalid\n";return 0;}base.push_back(x);}
 std::cin>>std::ws;if(!std::cin.eof()){std::cout<<"invalid\n";return 0;}
 using Clock=std::chrono::steady_clock;
 std::ofstream out("timings.tsv");if(!out){std::cout<<"io-error\n";return 0;}out<<"algorithm\titeration\telapsed_ns\n";
 for(int algorithm=0;algorithm<2;++algorithm){
  auto warm=base;if(algorithm==0)std::sort(warm.begin(),warm.end());else insertion(warm);if(!contract(base,warm))return 2;
  for(int iteration=0;iteration<5;++iteration){
   auto values=base;const auto start=Clock::now();
   if(algorithm==0)std::sort(values.begin(),values.end());else insertion(values);
   const auto end=Clock::now();if(!contract(base,values))return 3;
   const auto elapsed=std::chrono::duration_cast<std::chrono::nanoseconds>(end-start).count();if(elapsed<0)return 4;
   out<<(algorithm==0?"std_sort":"insertion")<<'\t'<<iteration<<'\t'<<elapsed<<'\n';
  }
 }
 out.close();if(!out){std::cout<<"io-error\n";return 0;}
 std::vector<int>counterexample{1,3,2},mutant=counterexample;
 for(std::size_t i=1;i+1<mutant.size();++i){int x=mutant[i];auto j=i;while(j>0&&x<mutant[j-1]){mutant[j]=mutant[j-1];--j;}mutant[j]=x;}
 if(contract(counterexample,mutant))return 5;
 std::cout<<"contracts PASS\nsamples 10\nmutation detected\n";
}

