#include <iostream>
#include <string>
#include <variant>
#include <type_traits>
enum class State { idle, running, paused, done };
struct Start {}; struct Pause {}; struct Resume {}; struct Finish {};
using Event = std::variant<Start, Pause, Resume, Finish>;
bool apply(State& state, const Event& event) {
  return std::visit([&](const auto& item) {
    using T = std::decay_t<decltype(item)>;
    if constexpr (std::is_same_v<T, Start>) { if (state == State::idle) { state = State::running; return true; } }
    else if constexpr (std::is_same_v<T, Pause>) { if (state == State::running) { state = State::paused; return true; } }
    else if constexpr (std::is_same_v<T, Resume>) { if (state == State::paused) { state = State::running; return true; } }
    else { if (state == State::running) { state = State::done; return true; } }
    return false;
  }, event);
}
int main() {
  std::string trace;
  if (!std::getline(std::cin, trace) || trace.size() > 100) { std::cout << "invalid\n"; return 0; }
  std::cin >> std::ws;
  if (!std::cin.eof()) { std::cout << "invalid\n"; return 0; }
  State state = State::idle; int rejected = 0;
  for (char c : trace) {
    bool ok = false;
    if (c == 'S') ok = apply(state, Start{});
    else if (c == 'P') ok = apply(state, Pause{});
    else if (c == 'R') ok = apply(state, Resume{});
    else if (c == 'F') ok = apply(state, Finish{});
    if (!ok) ++rejected;
  }
  const char* names[] = {"idle", "running", "paused", "done"};
  std::cout << names[static_cast<int>(state)] << " rejected " << rejected << '\n';
}

