#include <iostream>
#include <memory>
#include <map>
#include <vector>
#include <functional>
struct SignalState { int next = 1; std::map<int, std::function<void()>> handlers; };
class Subscription {
  std::weak_ptr<SignalState> state_; int id_;
public:
  Subscription(std::shared_ptr<SignalState> state, int id) : state_(state), id_(id) {}
  Subscription(const Subscription&) = delete;
  Subscription& operator=(const Subscription&) = delete;
  ~Subscription() { if (auto s = state_.lock()) s->handlers.erase(id_); }
};
void emit(const std::shared_ptr<SignalState>& s) {
  std::vector<int> ids;
  for (const auto& [id, handler] : s->handlers) ids.push_back(id);
  for (int id : ids) {
    auto it = s->handlers.find(id);
    if (it != s->handlers.end()) { auto handler = it->second; if (handler) handler(); }
  }
}
int main() {
  int mode;
  if (!(std::cin >> mode) || mode < 0 || mode > 2) { std::cout << "invalid\n"; return 0; }
  std::cin >> std::ws;
  if (!std::cin.eof()) { std::cout << "invalid\n"; return 0; }
  auto signal = std::make_shared<SignalState>();
  auto receiver = std::make_shared<int>(0); std::weak_ptr<int> weak = receiver;
  { int id = signal->next++;
    signal->handlers.emplace(id, [weak] { if (auto value = weak.lock()) ++*value; });
    Subscription subscription(signal, id);
    emit(signal);
    if (mode == 1) receiver.reset();
    if (mode == 2) signal->handlers.clear();
    emit(signal);
  }
  emit(signal);
  std::cout << "value " << (receiver ? *receiver : -1) << " subscriptions " << signal->handlers.size() << '\n';
}

#include <iostream>
class Job {
  int size_, done_ = 0, candidate_ = 0; bool cancelled_ = false;
public:
  explicit Job(int n) : size_(n) {}
  void cancel() { if (done_ < size_) cancelled_ = true; }
  void step() { if (cancelled_) return; int budget = 3; while (budget-- > 0 && done_ < size_) { ++done_; candidate_ += done_; } }
  bool finished() const { return done_ == size_; }
  bool cancelled() const { return cancelled_; }
  int done() const { return done_; }
  int result() const { return finished() ? candidate_ : 0; }
};
int main() {
  int n, cancelAt;
  if (!(std::cin >> n >> cancelAt) || n < 0 || n > 100 || cancelAt < -1 || cancelAt > 40) { std::cout << "invalid\n"; return 0; }
  std::cin >> std::ws;
  if (!std::cin.eof()) { std::cout << "invalid\n"; return 0; }
  Job job(n); int tick = 0;
  while (!job.finished() && !job.cancelled()) { if (tick == cancelAt) job.cancel(); if (!job.cancelled()) { job.step(); ++tick; } }
  std::cout << (job.cancelled() ? "cancelled" : "done") << " processed " << job.done() << " result " << job.result() << '\n';
}

